/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { ExploreScreen } from "../../src/explore/ExploreScreen.js";
import { GaiaCensusScreen } from "../../src/gaia-census/GaiaCensusScreen.js";
import HRDiagramColors from "../../src/HRDiagramColors.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { HRDiagramPreferencesModel } from "../../src/preferences/HRDiagramPreferencesModel.js";
import { RadiusScreen } from "../../src/radius/RadiusScreen.js";
import { StarSamplesScreen } from "../../src/star-samples/StarSamplesScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from hRDiagramQueryParameters.
  const simPreferences = new HRDiagramPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new ExploreScreen(simPreferences, {
      name: stringManager.getScreenNames().exploreStringProperty,
      tandem: Tandem.ROOT.createTandem("exploreScreen"),
      backgroundColorProperty: HRDiagramColors.backgroundColorProperty,
    }),
    new RadiusScreen(simPreferences, {
      name: stringManager.getScreenNames().radiusStringProperty,
      tandem: Tandem.ROOT.createTandem("radiusScreen"),
      backgroundColorProperty: HRDiagramColors.backgroundColorProperty,
    }),
    new StarSamplesScreen({
      name: stringManager.getScreenNames().starSamplesStringProperty,
      tandem: Tandem.ROOT.createTandem("starSamplesScreen"),
      backgroundColorProperty: HRDiagramColors.backgroundColorProperty,
    }),
    new GaiaCensusScreen({
      name: stringManager.getScreenNames().gaiaCensusStringProperty,
      tandem: Tandem.ROOT.createTandem("gaiaCensusScreen"),
      backgroundColorProperty: HRDiagramColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { HRDiagramColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
